        # Central shared state notebook dictionary
        self.state = {"topic": topic, "research": "", "draft": "", "review": "PENDING"}
        # Short-term memory message list
        self.short_term_memory = []
    # Helper method to append message to short-term memory
    def record_message(self, role, content):
        # Append role and content dictionary to list
        self.short_term_memory.append({"role": role, "content": content})

